INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('caterpillar-man', 'Caterpillar Men', 'monster', 'rifts', 0, 'Miscreant (75%) or other evil alignment', '{"IQ":"1D4+9","MA":"1D6+12","ME":"1D6+6","PS":"3D6+14","PP":"1D6+12","PE":"1D6+12","PB":"1D6+1","Spd":"1D6+4"}', NULL, NULL, '5D6+36+PE', '4D6+8', 'MEx2', 'MDC: plus 10 per level of experience. ISP: plus 1D6 per level of experience. P.S. counts as Robotic P.S. (low-end M.D. punches). Average level of experience 1D6+3.', NULL, 10, '{"attacks":4,"initiative":2,"strike":2,"disarm":1,"roll":3}', 'Horror Factor rises by 4 once it reveals itself and attacks. Attacks: 4 at first level, plus 1 at levels 3, 6, 9 and 12. Plus 4 automatic dodge (still rolled, costs no action), plus 3 on Perception Rolls, plus 4 vs Horror Factor, plus 6 vs poison and disease; impervious to spoiled meat and diseased blood, and apparently to the psychic imprint of Madhaven. Cannot hold a weapon. Anyone who spends over 15 minutes with one suffers dulled senses (no save): -3 Perception, -2 initiative, -1 strike, parry and dodge, and must save vs psionics (then hourly) or come to trust it.', 'Skill-like aptitudes: Prowl 50%, Climb 80/70%, Land Navigation 80%, Tailing 55%, Lore: D-Bees (and Haven Mutants) 75%, Wilderness Survival 90%. Speaks only American but understands any language at 75% (+1% per level) after 1D4 days of hearing it.', 'Mega-damage body; bio-regenerates 2D6 M.D.C. an hour and regrows lost parts in 1D6 days; nightvision 1000 ft, sees infrared, ultraviolet and the invisible, sees through murk and fog; immune to rot, foul water and most disease; bends and lunges with a 12-18 ft reach and automatic dodge; squeezes through gaps half its width; a soothing voice that works as a passive psionic lull.', 'None', 'Minor Psychic: Empathy (4, receive only), Mind Block (4), See Aura (6), Sense Time (2)', '18-22 feet (5.5-6.7 m) stretched out; usually hunched to 10-13 feet (3-3.9 m)', '400-600 lbs (180-270 kg)', 'Unknown; at least 80 years, perhaps two or three times that', 'Madhaven and Jersey Side in large numbers (up to about a thousand); lone ones or small groups across North and South America, mainly warm regions; sleep in caves, basements and other underground lairs', 'Mostly their own kind; sometimes serve other evil beings; keep company with humanoids only to hunt them', 'Head Worms; Onion Heads; most other humanoids, Haven Mutants included, as prey', NULL, 'Towering, caterpillar-bodied alien predators that walk on human legs, wear pants and boots, and play the polite, helpful local guide until they can kill and eat the people they befriend. Slavers pay 6,000-8,000 credits for one.', 'Rifts World Book 29: Madhaven p.92-94'),
('devil-kraken', 'Devil Kraken', 'monster', 'rifts', 0, 'Diabolic', '{"IQ":"2D6+10","ME":"2D6+12","MA":"2D6+6","PS":"5D6+24","PP":"2D6+6","PE":"3D6+12","PB":"2D6","Spd":"6D6+40"}', NULL, NULL, 'PEx200', '2D6x10+PE', NULL, 'MDC by location: Large Horn 1000, Small Horns (2) 400 each, Eyes (2) 60 each*, Teeth (over 100) 100 each*, Fins (4) 500 each, Tail Fin 1050, Plated Dorsal Fin 1000**, Dorsal Armor Plates (9) 1200 each**, Belly Armor Plates (9) 450 each**, Main Body P.E. x200. * Called Shot at -5. ** A dorsal or belly plate must be destroyed before the Main Body can be hit: one plate gone means a Called Shot at -8, two to four gone -2, more than four no penalty. P.S. and P.E. are supernatural.', NULL, 17, '{"attacks":7,"initiative":3,"strike":5,"parry":4,"dodge":2,"roll":3}', 'Plus 4 vs psionics, plus 4 vs magic, plus 3 on Perception Rolls.', 'Swim 98%, Prowl 63%. Chemoreceptor: identify chemicals by taste 60%, track by taste 50% (+20% for blood), 1 mile range. Sonic echolocation 15% +5% per level (1000 ft; to 2000 ft at -20%).', 'Nightvision 2000 ft and sees the invisible; bio-regenerates 6D6 M.D.C. an hour, armor plates 1D4x10 a day; depth tolerance five miles; senses magnetic north; electro-magnetic sense that reads brain and nerve activity (spots injuries, implants and psychics at 30 ft, follows vessel trails at 300 ft and earth energy lines at 3 miles); sonic echolocation that maps the water around it.', 'Ocean Magic: Air Swim, Breathe Air, Water Pulse, Flying Fish (self only), Impervious to Cold, Water Wall, Impervious to Electricity, Whirlpool, Communicate with Sea Creature, Change Current. Water Elemental: Command Fish, Hail, Shards of Ice, Wall of Ice, Hurricane, Summon Storm. Casts at 8th level.', 'None', '200 feet (61 m) long; the biggest known in the Sound exceeds 400 feet (122 m)', '60-110 tons', 'Unknown; perhaps 200-300 years', 'So far only Long Island Sound; could live in any salt or fresh water', 'None as such; solitary, but may command 2-8 lesser sea monsters such as Horned Demon-Fish, Aqua Hydras and Water Serpents; some have gone over to the Lord of the Deep', 'Humans, Horune Pirates, the Splugorth, and anyone who intrudes on or challenges it', NULL, 'Huge, spike-plated sea monster of Long Island Sound, also called the Demon of the Sound or Sea Spear, that sinks ships for the fun of watching crews drown. It leaves Horune ships alone but not their stragglers, and cannot be bothered with prey that fights too hard.', 'Rifts World Book 29: Madhaven p.94-96'),
('giant-ruin-worm', 'Giant Ruin Worm', 'monster', 'rifts', 0, 'Considered Diabolic predators', '{"IQ":"1D4+3","MA":"1D4","ME":"2D6","PS":"4D6+6","PP":"2D6+4","PE":"5D6","PB":"1D6","Spd":"4D6+50"}', NULL, NULL, '5D6x10+60', '4D6', NULL, 'Spd 4D6+50 is underground and underwater (about 38 mph); on the surface it is 1D6+25 (18-20 mph). P.S. and P.E. are supernatural.', NULL, 16, '{"attacks":3,"initiative":1,"strike":5,"dodge":1,"roll":1}', 'Horror Factor is 11 for Haven Mutants used to fighting them. Plus 5 vs mind control; impervious to possession, poison, Horror Factor and illusions. Half damage from blunt attacks. Retreats underground once reduced to half M.D.C.', 'Land Navigation 70%, Swim 70%, Prowl 60%. Cannot climb or squeeze through small openings.', 'Greasy hide that defeats grapples and halves blunt damage; no eyes, ears or nose; motion sense to a mile underground (95% on size, speed and pattern), 3000 ft underwater, 20 ft in open air; heat-sensing maw to 300 ft; bio-regenerates 4D6 M.D.C. an hour and regrows a tail or body section in 1D6+4 days; eats about once a month.', 'None', 'None', '28-36 feet long (8.5-10.9 m) and 6-8 feet wide (1.8-2.4 m) at the middle; mouth roughly 6 feet (1.8 m) across', 'Up to 8 tons', 'Unknown; 90 years or more, perhaps up to triple that', 'Beneath Madhaven and Jersey Side in the greatest numbers; smaller numbers under other big city ruins such as Washington D.C., Boston, Windsor, Detroit, Old Chicago, St. Louis, Calgary and Mexico City', 'None', 'Haven Mutants, who hunt and eat them; will eat mutants, humanoids, Ruin Rats, Ruin Lizards, demons and animals alike; left alone by Undead Horrors; Horune Pirates capture them for the arenas of Atlantis', NULL, 'Burrowing, eyeless giant worm of city ruins that erupts from rubble to swallow people whole, armor and all. It hunts by vibration, and anything it cannot finish off it leaves for easier prey.', 'Rifts World Book 29: Madhaven p.96-98'),
('head-worm', 'Head Worms', 'monster', 'rifts', 0, 'Considered Miscreant or Diabolic', '{"IQ":"1D6+4","MA":"3D4+2","ME":"2D4+2","PS":"2D4+12","PP":"1D4+16","PE":"2D4+12","PB":"1D4","Spd":"3D4+12"}', NULL, NULL, '3D6+28+PE', '4D6+8', 'MEx3', 'MDC: plus 2D6 each level; body armor can be worn. ISP: plus 2D4 per level of experience. Average level of experience 1D4+2.', NULL, 15, '{"attacks":4,"initiative":2,"strike":3,"parry":1,"dodge":3,"disarm":2,"roll":4}', 'Attacks: 4 at first level, plus 1 at levels 2, 4, 6, 8, 11 and 15. Plus 3 on Perception Rolls, plus 2 vs Horror Factor, plus 4 vs poison and disease; impervious to possession, rotting meat and diseased blood, and seemingly to the psychic imprint of Madhaven.', 'Skill-like aptitudes: Prowl 50%, Climb/Rappel 75/75%, Swim 70%, Land Navigation 80%, smells blood to 4000 ft, track by blood scent 80%, track by sight 65%. Speaks in short words and phrases; can understand and speak any language after 1D4 days of hearing it.', 'Mega-damage worm body with 11-13 small eyes; nightvision 1000 ft, sees infrared, ultraviolet and the invisible, and through murk and fog; bio-regenerates 2D6 M.D.C. an hour and regrows parts in 1D6+4 days; immune to rot, foul water and most disease; 1D4 small arms that can use weapons, guns included; harpoon tongue.', 'None', 'Minor Psychic: Mind Block (4), Deaden Senses (4), Death Trance (1), Telekinetic Push (4), plus one Physical psionic power of choice', '7-12 feet (2.1-3.6 m) long; rears up like a cobra to two-thirds its length', '300-450 lbs (135-202.5 kg)', 'Unknown; at least 50 years', 'Madhaven and Jersey Side (a few thousand); a few dozen to a hundred seen near Washington DC, Saint Louis, Windsor, Detroit and Old Chicago', 'Their own kind, Pseudo Men, Crazies, Psi-Stalkers, Shifters and some humans', 'Caterpillar Men, Undead Horrors, vampires, demons, Ruin Rats, Ruin Worms, and the Splugorth with all their minions; dislike creatures of magic, spell casters, cyborgs, Metal Morphs, Leopard Men and most humans', NULL, 'Big-headed, semi-intelligent worm predators, also called Hunter Worms or Worm Slaves, kept by Haven Mutants on leashes as attack animals and trackers. They are loyal to their handlers, especially Pseudo Men, but go wild in any fight. Slavers pay 10,000-15,000 credits.', 'Rifts World Book 29: Madhaven p.98-100'),
('onion-head', 'Onion Heads', 'monster', 'rifts', 0, 'Considered Anarchist (60%), Miscreant (20%) or other selfish or evil alignment', '{"IQ":"1D6+6","MA":"1D6+4","ME":"1D6+6","PS":"1D6+10","PP":"1D4+6","PE":"1D6+10","PB":"1D6","Spd":"1D6+2"}', NULL, NULL, '2D6+10+PE', '2D6', 'MEx10', 'MDC: plus 1D4 per level of experience. ISP: plus 1D4+4 per level of experience. Average level of experience 1D6+3.', NULL, 9, '{"attacks":3,"strike":1,"parry":1,"dodge":2,"disarm":1}', 'Attacks: 3 at first level, plus 1 at levels 3, 8 and 12. Plus 3 on Perception Rolls, plus 3 vs possession, plus 3 vs Horror Factor; impervious to poison, disease, acid and rotten food, and apparently to the psychic imprint of Madhaven and to the voice and psionics of Caterpillar Men.', 'Instinctive skills: Botany 75%, Brewing 80%, Climb 90/85%, Dowsing 65%, Holistic Medicine 60%, Identify Plants and Fruit 98%, Land Navigation 75%, Preserve Food 95%, Prowl 60%, Recycling 60%; trail food by scent to 1000 ft at 68% +2% per level (+12% to identify it); taste analysis 66% +2% per level; Swim 88%. Speaks garbled American.', 'Nightvision 1000 ft, sees in murky water; bio-regenerates 1D6 M.D.C. an hour and regrows parts in 2D6+24 hours; holds its breath a minute per P.E. point and survives 800 ft depths; sticks to walls and ceilings at one-third speed; secretes an organic acid that dissolves flesh and plants (1D6 S.D.C. to anyone touching it, one point of M.D. to M.D.C. skin).', 'None', 'Major Psychic: Commune with Spirits (6), Empathy (4), Meditation (0), Mind Block (4), Psychic Diagnosis (4), Psychic Purification (8), Telepathy (4), Bio-Manipulation (10), Electrokinesis (varies)', '3.5-4.5 feet (1.1-1.4 m) tall', '60-90 lbs (27-40.5 kg)', 'Unknown; believed 1D4x10+60 years', 'A few hundred scattered through Madhaven and Jersey Side, in clans of rarely more than 10-12; allowed to cross every border and clan territory', 'Their own kind in groups of 2D6; tolerate friendly folk who respect their gardens; Haven Mutants trade them produce and seeds for healing', 'Caterpillar Men; Ruin Rats and other garden pests; anyone who steals from or harms their gardens', NULL, 'Small, slug-like tentacled gardeners with bulb-shaped heads who dress in human clothes and grow crops among the ruins. Peaceful and stingy, they turn deadly with acid and psionics on anyone who raids a garden, and heal Haven Mutants in trade.', 'Rifts World Book 29: Madhaven p.100-102'),
('phantom-wolf', 'Phantom Wolf', 'monster', 'rifts', 0, 'Any; wild ones usually count as Anarchist or Miscreant', '{"IQ":"1D6+4","ME":"1D6+10","MA":"2D6+10","PS":"2D4+20","PP":"1D6+16","PE":"1D6+20","PB":"1D6+12","Spd":"2D4x10+40"}', NULL, NULL, '3D6x10+50', '1D6x10+PE', NULL, 'MDC: plus 3D6 per level of experience (reflects age). Spd 2D4x10+40 is 41-120 mph. P.S. and P.E. are supernatural. Average level of experience 1D4+2.', NULL, 14, '{"attacks":5,"initiative":1,"strike":4}', 'Plus 4 automatic dodge, plus 4 vs Horror Factor, plus 2 vs psionic and magic attacks, plus 5 vs poison, drugs and disease, plus 2 on Perception Rolls. A trained one answers its rider like a horse.', 'Land Navigation 80%, Prowl 72%, Swim 70%, track by scent 70% (+15% for magic and creatures of magic).', 'Leaps 10 ft high and 20 ft long; nightvision 2000 ft; always sees the invisible; bio-regenerates 3D6 M.D.C. an hour; a P.P.E. vampire that feeds on the life energy of its kills. Phantom Walk: turns itself and its rider semi-transparent and intangible for a minute per level (five minute rest between uses, doubled near a ley line, unlimited on one) - silent and invisible to sensors, +20% prowl, able to fight ghosts and Entities, untouchable by physical attacks, but unable to affect the physical world or pass through walls.', 'Chameleon (6), Sense Magic (4), Shadow Meld (10); duration by the wolf''s level', 'None', '10-13 feet (3-3.9 m) nose to rump plus a 3-4 foot (0.9-1.2 m) tail; 6-8 feet (1.8-2.4 m) at the shoulder', '900-1200 lbs (405-540 kg)', '2D6+28 years', 'Woodlands in and around Madhaven and across the Northeast, Delaware to Maine and into New Brunswick', 'Their own kind and Dark Hounds; can be tamed if raised young by humans, Psi-Stalkers, Simvan or Haven Mutants', 'Ruin Rats, large animals, humanoids, supernatural beings and creatures of magic; Splugorth minions (Slavers, Blind Warrior Women, Horune) who hunt them', 'Riding animal: used as a combat mount by the Order of the White Rose (35 bred so far, 4D6+5 in the stables at any time, given TW barding) and by Haven Mutants and barbarians; worth 30,000-60,000 credits, double in Atlantis.', 'Huge black wolf-like creature of magic, also called Black Dog, Black Hound or Ghost Dog, that feeds on P.P.E. rather than flesh. It is a prized riding animal because it can carry its rider into ghostly intangibility.', 'Rifts World Book 29: Madhaven p.102-103'),
('ruin-lizard', 'Ruin Lizard', 'animal', 'rifts', 0, 'Considered Anarchist or Unprincipled', '{"IQ":"1D4+1","MA":"1D6+1","ME":"1D6+6","PS":"1D6+20","PP":"1D6+10","PE":"1D6+10","PB":"1D6","Spd":"2D6+38"}', NULL, NULL, '3D6x10+100', '3D6', NULL, 'MDC by location: Head 1D4x10+50, Front Legs (2) 1D6x10+60 each, Rear Legs (2) 1D8x10+80 each, Hands/Feet (4) 4D6+25 each, Tail 1D6x10+30, Main Body 3D6x10+100. Spd is about 30 mph. P.S. and P.E. are supernatural. Average level of experience: not applicable.', NULL, 9, '{"strike":2,"dodge":4,"roll":3}', 'Horror Factor 9 applies only to outsiders seeing one for the first time; none for Madhaven locals. Attacks: four for females, five for males. Plus 6 automatic dodge while running only, plus 4 vs Horror Factor, plus 2 vs poison, drugs and disease. Prefers to flee or play dead.', 'Swim 96%.', 'Nightvision 2000 ft; holds its breath 10 minutes and survives depths to one mile; sticky six-toed feet let it cling to walls and hang upside down at half speed; leaps 20 ft high and 40 ft across; calm and tolerant of people; Play Dead: curls up and passes as dead 01-85%.', 'None', 'None', '7-11 feet (2.1-3.3 m) nose to rump plus a 4-6 foot (1.2-1.8 m) tail; 5-6 feet (1.5-1.8 m) at the shoulder, 4-5 feet (1.2-1.5 m) wide', '1-2.5 tons', '2D6+30 years', 'Madhaven and Jersey Side; fewer on the coast between Maryland and North Carolina; hibernates in burrows in winter', 'None as such; travels in pairs or groups of 2D6', 'Ruin Rat packs prey on the young, old and hurt; a favorite food of the Devil Kraken at sea', 'Riding animal: ridden by Madhaven Leopard Men and the odd Dyno-Man; an awkward, bouncy mount most riders sit sidesaddle or crouched on. Worth 700-1400 credits as a mount; a leg of meat sells for 60 credits.', 'Horse-sized alien amphibian mistaken for a lizard, gentle toward people, that eats almost anything including young Ruin Rats. It can be trained as a leaping, wall-clinging riding animal, though a poor one.', 'Rifts World Book 29: Madhaven p.104-105'),
('ruin-rat', 'Ruin Rats', 'mutant', 'rifts', 0, 'Considered Anarchist or Miscreant', '{"IQ":"1D6","MA":"1D4","ME":"2D4","PS":"1D6+11","PP":"1D6+9","PE":"1D6+15","PB":"1D6","Spd":"2D6+22"}', NULL, NULL, '4D6+18', '6D6', 'ME+3D6', 'Spd printed as 22+2D6. P.S. and P.E. are supernatural.', NULL, 9, '{"attacks":4,"strike":3,"parry":1,"dodge":4,"roll":2}', 'Horror Factor 16 for a swarm of 10 or more. Plus 5 vs Horror Factor, plus 1 vs psionic attacks, plus 5 vs poison, drugs and disease, plus 1 on Perception Rolls. Packs pin a victim''s leg while others attack.', 'Prowl 90%, Swim 60%, Acrobatics 70%, track by scent 80%.', 'Nightvision 2000 ft; leaps 10 ft high and 20 ft across (+30% running); smells blood and decay 2 miles off and can tell when prey is ill or near death; squeezes through openings a third its size.', 'None', 'Presence Sense (4), Sixth Sense (2), See Aura (6), See Invisible (4)', '3-5 feet (0.9-1.5 m) nose to rump plus a 4-6 foot (1.2-1.8 m) tail; about 2 feet (0.6 m) high when on four legs, 3-5 feet when rearing', '100-150 lbs (45-67.5 kg)', '1D6+4 years', 'Madhaven by the thousands and Jersey Side in smaller numbers; found nowhere else', 'Pairs, trios and packs of 1D6x10 of their kind or ordinary rats', 'Haven Mutants (each hunts the other); prey on children, the sick and injured, and livestock; also attack Ruin Worms, Mystic Knights and outsiders', NULL, 'Dog-sized rats mutated into supernaturally strong, fearless scavenger-predators that raid camps in packs and drag off the weak. Their tasty meat sells for a credit per two pounds.', 'Rifts World Book 29: Madhaven p.105-106'),
('toothback-wallcrawler', 'Toothback Wallcrawler', 'monster', 'rifts', 0, 'Considered Miscreant or Diabolic', '{"IQ":"1D4+3","MA":"1D4","ME":"2D4","PS":"1D6+16","PP":"1D6+14","PE":"1D6+12","PB":"1D4","Spd":"1D6+16"}', NULL, NULL, '6D6+32', '4D6', NULL, 'Young have half the stats.', NULL, 13, '{"attacks":6,"strike":2,"parry":4,"dodge":1,"disarm":2,"pull":3,"roll":4}', 'Plus 4 vs Horror Factor, plus 3 vs poison, drugs and disease; impervious to spoiled meat and foul water. Young do half damage.', 'Prowl 60%, Climb walls and cliffs 85/75%, Swim 50%, Land Navigation 60%, track by scent 70%.', 'Nightvision 1000 ft; smells blood and human sweat to 3000 ft; double-jointed six legs let it squeeze through far smaller gaps than its body; lands on its feet from falls up to 1000 ft; leaps 12 ft high or 15 ft long; immune to most disease; chews M.D.C. bone and flesh.', 'None', 'None', '5-7 feet (1.5-2.1 m) long and 3 feet (0.9 m) tall; rears to 5 feet partly or 7-9 feet (2.1-2.7 m) fully upright', '300-400 lbs (135-180 kg)', '2D6+26 years', 'Madhaven and Jersey Side ruins in large numbers; pockets in the eastern mountains (Allegheny and Appalachian); caves, ruins and mountains, never forests', 'None, not even its own kind, though they share resting places (3D6+6 in a roost; nests of a pair and 1D4+1 young)', 'Preys mostly on mutants, humans and D-Bees; sometimes livestock and demons', NULL, 'Grey, wrinkled, six-legged alien ambusher with a small front mouth and a huge bone-cutting maw on its back. It creeps along walls and ceilings and hunts alone, mostly by day. Its meat is inedible and it fetches about 100 credits as an arena beast.', 'Rifts World Book 29: Madhaven p.106-107'),
('war-bird', 'War Birds', 'monster', 'rifts', 0, 'Most are considered Unprincipled or Scrupulous', '{"IQ":"1D6+4","ME":"2D6+2","MA":"2D6+6","PS":"2D6+16","PP":"1D6+15","PE":"2D6+11","PB":"1D6+16","Spd":"2D6"}', NULL, NULL, '4D4x10+PE', '1D6x10+PE', '1D4x10', 'MDC: plus 1D8 per level of experience; the Energy Aura adds 1D6x10+70 more while active. Spd 2D6 is on the ground; flying speed is 1D6x10+30 (40-100 mph), dives at double that (counts as two actions), ceiling about four miles. Attributes are supernatural. Average level of experience 1D6+2.', NULL, 11, '{"attacks":5,"initiative":3,"strike":4,"parry":1,"roll":3,"pull":4}', 'Horror Factor plus 3 while the magic aura is up. Plus 6 automatic dodge in flight, plus 3 on Perception Rolls, plus 4 vs psionics, plus 2 vs Horror Factor at levels 1, 3, 6, 9, 12 and 15. Rider bonded to it gains +20% Horsemanship: Exotic, +1 attack while mounted, +2 initiative, +1 strike, +2 dodge in flight, +12 M.D. to melee weapon attacks in a dive.', 'Land Navigation 90%, Track (by sight) 78%.', 'Flight to about 23,000 ft; hawk-like sight (a campfire at two miles); supernatural strength and endurance; bio-regenerates 1D8 (or 2D4) M.D.C. an hour. Energy Aura against M.D.C. foes: extra M.D.C., half damage from energy and magic fire, extra talon damage, 1D6 M.D. to anyone touching it. Energy Blast from the mouth while the aura is up. Telepathic Bond with a rider after three months, giving free two-way telepathy and empathy to 1000 ft.', 'None (a creature of magic; its aura is innate)', 'Empathy (4) and the rider bond', '10 feet (3 m) tall; wingspan 25-30 feet (7.6-9.1 m)', '700-1000 lbs (315-450 kg)', 'Uncertain; believed 1D6x10+60 years', 'Woods around Madhaven and the Catskills; now and then elsewhere in New York and southern Pennsylvania', 'Their own kind and mate (for life); White Rose Mystic Knights can tame them with patience, perhaps by other humans, Psi-Stalkers or Simvan', 'Blood Hawks (fight to the death); anything threatening mate, young, nest or forest - loggers, miners, flyers in its airspace; preys on deer, goats, livestock and travelers', 'Riding animal: flying mount of the White Rose knights (24 of them form the air unit The Rose''s Thorn); bonds only with Mystic Knights, and if its knight dies there is a 01-70% chance it dies within 1D4 weeks.', 'Giant eagle-like creature of magic, also called Little Thunder Bird or Storm Hawk, that guards a ten-mile territory of forest and wreathes itself in blue mystic energy to fight. Its feathers are thought lucky by some tribes.', 'Rifts World Book 29: Madhaven p.107-109'),
('gluttonous-entity', 'Gluttonous Entity', 'entity', 'rifts', 0, 'Anarchist (50%), Miscreant (40%) or Diabolic (10%)', '{"IQ":"1D4+9","ME":"1D6","MA":"1D4","PS":"N/A","PP":"N/A","PE":"N/A","PB":"N/A","Spd":"14"}', NULL, NULL, '2D6x10', '2D6', '1D6+20', 'All other attributes printed as inapplicable. Prefers to fuel psionics with I.S.P. stolen from people nearby (a failed save vs psionic attack costs the victim 2 P.P.E. or 10 I.S.P.). Regains 1D6 lost M.D.C. per hour. Needs 15 P.P.E. a day to subsist but craves 50.', NULL, 13, '{"attacks":3}', '+2 on saves against psionic attacks and magic. Vulnerable to protection circles and to Banishment, Commune with Spirits, Constrain Being, Control/Enslave Entity, Exorcism, Summon and Control Entity; magic attacks do full damage. Its greed makes it easy to trick with worthless bait.', 'Tailing 55%, Streetwise: Drugs 40%, Streetwise 50%, Seduction 60%, Recognize Weapon Quality 30%, Pick Pockets 80% (done with Telekinesis), Barter 90%, Appraise Goods 80%.', 'Invisible and intangible by nature; can turn visible for 4D6 minutes at a time. Never eats, sleeps or breathes. Energy and physical attacks, the physical side of psionics and magic, illusions, mind control and Horror Factor cannot touch it. Sees the invisible and sees in the dark to 2000 feet (610 m). P.P.E. vampire: siphons 1D4+1 P.P.E. from spells cast in strong emotion within 20 feet (6.1 m), or 1D6+3 when riding a willing caster''s back.', 'None.', 'Empathy, Mind Block, Presence Sense, See Aura, Sense Magic, Telekinesis, Telepathy and Empathic Transmission, as a 4th level psychic.', NULL, NULL, NULL, 'Madhaven, Jersey Side and other haunted places tied to memories of the past.', NULL, NULL, NULL, 'A greed-imprinted ghost that hoards valuables it cannot use, goads envious mortals into crimes, then steals the prize and leaves them to take the fall; appears as a well-dressed but ugly or miserly figure, or a green sphere of light.', 'Rifts World Book 29: Madhaven p.109-111'),
('beautiful-ghost', 'Beautiful Ghost', 'entity', 'rifts', 0, 'Can range from Scrupulous to Diabolic', '{"IQ":"N/A","ME":"N/A","MA":"N/A","PS":"N/A","PP":"N/A","PE":"N/A","PB":"1D6+16","Spd":"2D4+30"}', NULL, NULL, '4D6+10', '10', '30', 'All other attributes printed as inapplicable. Prints an Awe Factor of 12, which becomes a Horror Factor only when the ghost turns possessive, violent or vengeful (stored in horror_factor). A failed save vs psionic attack costs the victim 1D4 P.P.E. or 10 I.S.P.; siphons 1D4 P.P.E. from companions within 10 feet (3 m); needs 12 P.P.E. a day (mournful and angry ones double that). Regains 2D6 M.D.C. per hour.', NULL, 12, '{"attacks":3}', 'Attacks are via psionics. +2 on saves against magic, +3 against psionics. Vulnerable to protection circles and to Banishment, Commune with Spirits, Constrain Being, Control/Enslave Entity, Exorcism, Summon and Control Entity; magic does full damage. Ugliness and cruelty repel it: ignores anyone with P.B. under 7.', NULL, 'Invisible and intangible by nature; can turn visible at will for 3D6+10 minutes at a time. Never eats, sleeps or breathes. Physical attacks, the physical side of psionics and magic, illusions, mind control and Horror Factor cannot touch it. Sees in the dark to 2000 feet (610 m).', 'None.', 'Empathy, Empathic Transmission, Mind Block, Presence Sense, Telepathy and Ectoplasm, as a 6th level psychic.', NULL, NULL, NULL, 'Madhaven, Jersey Side and other haunted places tied to memories of the past.', NULL, NULL, NULL, 'A glowing, alluring female spirit drawn to imprints of love and desire; good ones are gentle flirts, mournful ones cling possessively to men who remind them of a lost love, and vengeful ones lure men into ruin.', 'Rifts World Book 29: Madhaven p.111-112'),
('harmful-ghost', 'Harmful Ghost', 'entity', 'rifts', 0, 'Diabolic or Miscreant', '{"ME":"1D4","MA":"1D4","PS":"1D6+10","PP":"1D6+4","PE":"N/A","PB":"1D4","Spd":"1D6+10"}', NULL, NULL, '6D6+30', '1D6x10', '36', 'I.Q. is printed only as ''average'' and is left unrolled. Spd is its silent hover/float (up to 4 feet/1.2 m off the ground); walking or crawling is Spd 1D6+1. A Greater Entity. Regains 3D6 M.D.C. per hour. A failed save vs psionic attack costs the victim 4 P.P.E. or 12 I.S.P.; needs 24 P.P.E. a day and seeks double.', NULL, 15, '{"attacks":3}', 'Attacks via magic or psionics. +6 to save vs spell magic, +3 vs psionics, +3 vs mind control. Sunlight bars its magic and does 1 M.D. per melee round; Globe of Daylight does the same and Lightblade strikes do full damage. Also affected by protection circles and by Banishment, Commune with Spirits, Constrain Being, Control/Enslave Entity, Exorcism and Expel Demons. Bound to 1D4 Haunted Focus objects kept hidden within 30 miles (48 km); threatening one lets it be blackmailed, and destroying all of them ends it.', 'Prowl 80%; speaks and reads the languages it knew in life at only 30%.', 'Invisible and intangible by nature (only half-power psionics in that state); can hold a visible, even solid ectoplasmic form as long as a living humanoid is within 100 feet (30.5 m). Never eats, sleeps or breathes. Energy and physical attacks, illusions, mind control and Horror Factor cannot touch it. Sees the invisible and sees in the dark to 2000 feet (610 m). Electromagnetic Disturbance: garbles electronics and cybernetics within 100 feet (30.5 m); sensors suffer -20%. Aura of Fear: humans within 100 feet are -5 to save vs Horror Factor, and those sensitive to the supernatural cannot rest (-20% skills); fades outdoors by day.', 'Spells at 5th level potency: Horror, Fear, Shadow Meld, Heavy Breathing, Fingers of the Wind, Seal, Horrific Illusion, Hallucination, Shatter, Wither Plants, Spoil: Water & Food.', 'Telepathy, Empathy, Ectoplasm, Telekinesis, Telekinetic Punch, Telekinetic Push and Bio-Manipulation.', NULL, NULL, NULL, 'Madhaven and, less so, Jersey Side; may turn up anywhere in the Megaverse.', NULL, 'Anyone who disturbs its Haunted Focus or reminds it of those it blames for its death.', NULL, 'A Greater Entity carrying the rage of someone who died betrayed or violently; shows as a pale, angry corpse bearing the wounds that killed it, and hunts whoever disturbs the keepsakes and places tied to its old life.', 'Rifts World Book 29: Madhaven p.112-114'),
('madness-ghost', 'Madness Ghost', 'entity', 'rifts', 0, 'Diabolic', '{"IQ":"1D6+9","ME":"N/A","MA":"N/A","PS":"N/A","PP":"N/A","PE":"N/A","PB":"N/A","Spd":"3D6+10"}', NULL, NULL, '4D6+20', '2D6+13', '2D6+50', 'Other attributes printed as not applicable; moves only by floating or flying. A Greater Entity. Regains 2D6 M.D.C. per hour. P.P.E. is printed twice (2D6+13 and 13+2D6). Steals 1D6+6 P.P.E. on contact via possession, Drain Sanity or nightmare; needs 18 P.P.E. a week and gorges on triple that. A failed save vs psionic attack costs the victim 4 P.P.E. or 12 I.S.P.', NULL, 16, '{"attacks":4,"dodge":5}', 'Impervious to Horror Factor. Vulnerable to psionic and magic attacks generally, Sheltering Force, Circle of Protection, Mind Block and Mind Block Auto-Defense, psionic Exorcism (always dispels it), Empathic Transmission, and the spells Banishment, Commune with Spirits, Constrain Being, Control/Enslave Entity and Exorcism. In astral form a character''s normal S.D.C. attacks do M.D. to it. Pulled off a victim by Psychic Surgery, Ectoplasm, Astral Projection or any Astral Being; silver does 1D4 M.D. and breaks its hold, as do daylight and holy water; Psi-Swords and rune weapons do full damage (half vs the nightmare form).', NULL, 'Invisible and intangible by nature, visible at will. Never eats, sleeps or breathes. Physical attacks, most psionics and magic, illusions, mind control and Horror Factor cannot touch it. Sees the invisible and sees in the dark to 3000 feet (914 m). Limited Possession: forces into a victim''s mouth (dodge, then its strike vs the victim''s parry) and turns him into a raving lunatic for 2D6 minutes. Drain Sanity: over days steals 1D4 M.E. a day, one insanity per 4 points lost; at M.E. zero the victim becomes a Madhaven Lunatic. Cause Nightmares: a psionic attack on sleepers with no save bonuses.', 'Spells at 5th level potency: Befuddle, Calling, Compulsion, Fear and Heavy Breathing.', 'Detect Psionics, Empathy, Ectoplasm, Presence Sense, Telekinesis, Telepathy and Psychosomatic Disease.', NULL, NULL, NULL, 'Madhaven; rare anywhere else.', 'None; a solitary fiend that never teams up with other spirits or supernatural powers.', NULL, NULL, 'A Greater Entity found by the thousands in Madhaven and almost nowhere else; a screaming face or green mist that possesses, drains the sanity of, and haunts the dreams of outsiders rather than killing them.', 'Rifts World Book 29: Madhaven p.114-116'),
('conglomerate-entity', 'Conglomerate Entity', 'entity', 'rifts', 0, 'Every alignment among its 2D6+12 personalities, but Diabolic overall', '{"IQ":"N/A","ME":"N/A","MA":"N/A","PS":"2D6+16","PP":"1D6+16","PE":"N/A","PB":"N/A","Spd":"1D6+16"}', NULL, NULL, '4D6x10+20', '5D6', '3D4x10+30', 'P.S. is Supernatural; Spd is floating/flying; all other attributes inapplicable. A Greater Entity, also called the Soul Collector Ghost. The largest carry another 2D6+12 personalities and another 2D6x10+66 M.D.C. Regains 2D6 M.D.C. per melee round, plus 1D6x10+10 on killing a human, D-Bee or mutant and 3D6x10+30 on slaying a supernatural or magical being. Flees at 25 M.D.C. unless berserk. Cannot draw I.S.P. from others. Takes 1 P.P.E. from each foe it fights; needs 30 P.P.E. a day.', NULL, 17, '{"attacks":9,"strike":2,"parry":6,"disarm":6}', 'Bonuses are in addition to attribute bonuses. +2 to save vs magic and psionics, +6 vs Horror Factor, +10 vs mind control; impervious to possession. Physical attacks, energy, fire, heat, cold and lightning do half damage. Silver weapons do their normal damage as M.D.; rune and other magic weapons half (a Soul-Drinking Rune Weapon strips a personality and 1D4x10 M.D. not recoverable for 48 hours); Psi-Sword full; holy weapons double. Cannot be controlled by Charm, Compulsion, Domination, mind control or Control/Enslave Entity. May ignore (01-60%) one or two people who stay still and silent or play dead.', NULL, 'A solid ectoplasmic body that never turns invisible and can squeeze through a keyhole-sized gap. Nightvision 4000 feet (1219 m), sees the invisible. Collect Souls: anyone dying within 100 feet (30.5 m) must save vs magic (18 or higher) or be absorbed into it; one action of concentration.', 'None.', 'Bio-Manipulation, Electro-Kinesis, Pyrokinesis, Telekinesis, Telekinetic Lift, Telekinetic Punch and Telekinetic Push, as a 6th level psychic.', NULL, NULL, NULL, 'Sites of mass death, always singly: Calgary, Detroit, Jersey Side, Madhaven, St. Louis, Tolkeen, Windsor and the like; in China some are captured to serve as torturers.', 'Sometimes summoned as guards or berserkers by evil Shifters, Necromancers and Demon Lords.', NULL, NULL, 'A Greater Entity born where many died violently: a floating mass of dozens of melting faces and 1D6+6 arms, each soul within fighting for control, so it lurches between cruelty, fear and rage and grows by absorbing the souls of those who die near it.', 'Rifts World Book 29: Madhaven p.117-119'),
('contagion-entity', 'Contagion Entity', 'entity', 'rifts', 0, 'Diabolic and hateful', NULL, NULL, NULL, '6D6+30', '2D6+7', '4D6+15', 'Stats are for the host/carrier fused with the Entity. Attributes are the host''s own (human or D-Bee only) with P.S. made Supernatural, so none are rolled here. The host''s Hit Points and S.D.C. become M.D.C.; 6D6+30 is the typical NPC villain, and the Entity alone as an energy being has 1D4x10+10 M.D.C. An M.D.C. being cannot be a host. P.P.E. prints as 2D6+7 in the pools line but the Magic entry says to re-roll it as 2D6+6. Bio-regenerates 1D6 M.D.C. per melee round. Needs 13 P.P.E. a day, can go two weeks unfed, and can gorge on 60 a day (bonuses halved for 1D6 hours). Draws I.S.P. from others like most Entities.', NULL, 15, '{"parry":2,"dodge":4,"disarm":2,"pull":4}', 'Horror Factor applies only to those who know what the carrier is. Attacks per melee are the host''s by O.C.C. and level (two in energy form; 4 or 5 is typical for a carrier). Bonuses are in addition to the host''s: +2 to Perception Rolls, +4 to save vs Horror Factor; impervious to possession, mind control, poison, disease and radiation; drugs work at half effect for a third of the duration. Haven Mutants save against it at +3.', 'As the host''s O.C.C., never a practitioner of magic; about half are Vagabonds or adventurer types.', 'The host keeps his memories, skills and O.C.C. abilities, gains Supernatural P.S. and becomes a lesser M.D.C. being, and is cured of all prior injury and illness. Contagion: a magical plague carried in blood, saliva and mucus; anyone exposed must save vs disease at half bonuses, needing 17 or higher, and re-save each exposure after 24 hours. The sick lose S.D.C. from day three and then 1D6 Hit Points a day from day six until death. Only exorcising (01-50%) or destroying the carrier ends it.', 'None; any former magic is lost.', 'The host''s psionics are lost. The Entity alone, only in energy sphere form, has Telepathy, Empathy, Empathic Transmission, Radiate Horror Factor and See Aura as a 3rd level psychic.', NULL, NULL, NULL, 'Rare anywhere; most often seen in Africa, China, India, Jersey Side, Madhaven and the ruined cities of Windsor and Detroit; carriers hide in crowded slums.', NULL, 'Psi-Net, Dog Boys and psychic healers who hunt carriers; Haven Mutants and Haven Shamans destroy them on sight.', 'The host may be of any O.C.C. except a practitioner of magic.', 'A Greater Entity of disease-laden negative energy that merges with a willing, hate-filled human or D-Bee, turning him into a Mega-Damage carrier of a magical plague who spreads it deliberately and hides among the sick.', 'Rifts World Book 29: Madhaven p.119-122'),
('rotting-entity', 'Rotting Entity', 'entity', 'rifts', 0, 'Diabolic', '{"IQ":"1D6+6","ME":"1D6","MA":"1D4","PS":"2D6+14","PP":"1D6+13","PE":"N/A","PB":"1D4","Spd":"1D6+14"}', NULL, NULL, '2D6x10+27', '1D4x10+40', '1D4x10+20', 'P.S. is Supernatural. Spd is running; hovering and floating is double. A Greater Entity bound to a corpse no more than 48 hours dead. Regenerates 1D4 M.D.C. per melee round and grafts a lost limb from a dead body in 1D4 melee rounds. Draws 1D6+5 P.P.E. each time it rots a limb; needs 20 P.P.E. a day, can go two weeks unfed, and can gorge on 45 a day (bonuses halved for 1D4 hours). A failed save vs psionic attack costs the victim 3 P.P.E. or 10 I.S.P.', NULL, 15, '{"attacks":4,"initiative":1,"strike":2,"dodge":2,"disarm":2,"entangle":2,"pull":3}', 'Bonuses are in addition to attribute bonuses. +2 on saves vs psionics and magic. Immune to disease, drugs, energy weapons, Horror Factor, illusions, mind control, poisons, possession and S.D.C. damage. Silver or iron weapons do double their damage as M.D.; holy weapons full; magic spells and weapons half; M.D. punches, bullets and explosives half. Subject to Banishment, Commune with Spirits, Constrain Being, Control/Enslave Entity, Exorcism, Summon Lesser Being, and Summon and Control Entity; Protection Circles and Sheltering Force hold it out. Only one Rotting Touch per melee round.', 'Tracking (people) 60%, Tailing 60%, Prowl 60%, Land Navigation 80%, Climb 60%/50%; speaks every language at 85%.', 'Nightvision 2000 feet (610 m), sees the invisible, and can touch and harm intangible beings including other Entities. No need to eat, sleep or breathe. Noxious Odor: within 20 feet (6.1 m) victims must save vs poison (14 or higher) or vomit, -3 to strike, parry and dodge until 300 feet (91.5 m) away; sealed armor or gas masks protect, air filters give +2. Maggots taken from its body within 10 minutes of its death restore rotted limbs.', 'Agony, Calling, Heal Wounds and all Spoiling Magic, as a 4th level sorcerer.', 'Deaden Pain, Detect Psionics, Healing Touch, Psychic Diagnosis, Psychic Surgery, Stop Bleeding, Telepathy, See Aura, Sense Magic and Sense Evil, as a 4th level psychic.', NULL, NULL, NULL, 'Wherever victims are plentiful: Africa, Calgary, China, Detroit, India, Jersey Side, Madhaven, old Chicago''s ruins, St. Louis and Windsor.', 'None as such; sometimes forced to serve a Shifter, Necromancer, Demon Lord or Dark God.', 'Mortals, and anyone who tries to enslave or command it.', NULL, 'A demon-like spirit that inhabits a fresh corpse and wears it as a tall, gaunt, maggot-ridden body; it rots food, wood and living flesh with a touch and uses the threat of maiming to bully and enslave mortals.', 'Rifts World Book 29: Madhaven p.122-124'),
('beast-men', 'Beast Men', 'mutant', 'rifts', 1, 'Any; most are Scrupulous (25%), Unprincipled (20%) or Anarchist (40%)', '{"IQ":"2D6+12","ME":"2D6+10","MA":"2D6+8","PS":"3D6+18","PP":"2D6+12","PE":"3D6+3","PB":"2D6+4","Spd":"3D6"}', NULL, NULL, '2D4x10+50+PE', '2D6+PE', NULL, 'MDC: plus 2D6 per level of experience. Supernatural P.S., so full-strength blows deal M.D. H.F. 12 when a group of them brandish big guns or strange gadgets. Average NPC level 1D6+5.', NULL, 9, '{"attacks":4,"parry":1,"pull":3,"roll":1}', 'Attacks per Hand to Hand: Expert (four at level one); damage per the Supernatural P.S. table. +2 to disarm on a Called Shot with modern firearms or energy weapons, +4 to save vs Horror Factor, +2 vs mind control, +4 vs possession, +4 on Perception Rolls. Shaman overlay (p.79): a clan Shaman of this race adds +2 I.Q., +1D4+2 M.A., +3D6+10 P.P.E. (+1D6 per level), a set of lore and healing skills that replace Secondary, Pilot and W.P. Modern skills, and prayers to Isis.', 'Appraise Goods +15%, Art +20%, Automotive Mechanics +15%, Basic Electronics +15%, Computer Operation +15%, Computer Repair +10%, Computer Hacking +5%, Creative Writing +10%, Jury-Rig +10%, Land Navigation +10%, Language: American (native), Literacy: American +30%, Math: Basic +30%, Math: Advanced +15%, Mechanical Engineer +10%, Pilot two vehicles (no robots or power armor), Prowl +5%, Salvage +20%, Sensory Equipment +10%, Vehicle Armorer +15%, W.P. one Ancient, W.P. two Modern, Hand to Hand: Expert (fixed); 1D4+3 Secondary Skills plus two more at each of levels 2/4/6/8/12/14.', 'Very strong and clever, with a knack for machines, construction and art. Haven Mutant traits (p.60): immune to the Madhaven psychic imprint, empathic transmission, Entity fear and Horror Factor, and mind or emotion affecting psionics and magic; still hurt by physical psionics, most magic and physical attacks. Juicer conversion does not work; M.O.M. implants kill in 1D6 days; cannot learn to pilot power armor or robots.', 'None; shuns magic.', 'None.', '6-7 ft (1.8-2.1 m)', '260-400 lbs (117 to 180 kg)', '80, some to 118; females live 2D4 years longer', 'Madhaven ruins at or under ground level; tidy lairs marked by murals and graffiti', 'Own clan and other mutants; a wary truce with the White Rose knights; trade with Horune Pirates and Slavers without trusting them', 'Invaders and outsiders in general, madmen, ghosts, Undead Horrors, monsters and magic creatures; wary of Barbarians, Splugorth Minions and Horune Pirates, though trade goes on with each', NULL, 'Furry, ape-faced giants who are the tinkerers and engineers of the mutant clans, building and trading the vehicles and weapons the other races use, and happy to pilfer outsiders'' gear to study it.', 'Rifts World Book 29: Madhaven p.60-62'),
('dyno-men', 'Dyno-Men', 'mutant', 'rifts', 1, 'Any; most are Unprincipled (10%), Anarchist (30%), Aberrant (20%) or Miscreant (30%)', '{"IQ":"1D6+6","ME":"1D6+7","MA":"1D6+2","PS":"3D6+26","PP":"2D6+10","PE":"3D6+10","PB":"1D6","Spd":"2D6"}', NULL, NULL, '1D6x100+PE', 'PE', 'MEx10', 'MDC: plus 2D6 per level of experience; recovers 6D6 M.D.C. per 12 hours. ISP: plus 1D6 per level. Spd 2D6 is on dry land; underwater Spd is 2D4x10. P.S. is Supernatural. H.F. 14 in a war or hunting band of 6+. Average NPC level 1D4+2.', NULL, 12, '{"attacks":5,"initiative":1,"strike":3,"parry":3,"dodge":3,"disarm":1,"pull":2,"roll":1}', 'Five attacks at level 1, gaining one at levels 3/6/9/12/15; damage per the Supernatural P.S. table. The listed combat bonuses are for dry land (+1 entangle too) and are doubled underwater. Always: +7 to save vs Horror Factor, +3 vs mind control, +5 vs possession, +4 vs poison, pollution and drugs. Shaman overlay (p.79): a clan Shaman of this race adds +2 I.Q., +1D4+2 M.A., +3D6+10 P.P.E. (+1D6 per level), a set of lore and healing skills that replace Secondary, Pilot and W.P. Modern skills, and prayers to Isis.', 'Dowsing +20%, Fishing +20%, Holistic Medicine +10%, Hunting, Identify Plants & Fruits +20%, Land Navigation +10%, Language: American (native), Lore: Demons & Monsters +15%, Lore: Magic +10%, Math: Basic +10%, Navigation +15%, Pilot: Boat, Paddle +10%, Preserve Food +15%, Prowl +15% in water only; Skin & Prepare Animal Hides +15%, Swimming +30%, Wilderness Survival +20%, two Wilderness skills +10%, W.P. Knife, W.P. three Ancient, W.P. one Modern; 1D4+3 Secondary Skills plus one more at levels 2, 5, 8, 11 and 14.', 'Amphibious: breathes water, swims, survives 1200 ft depths, holds breath a minute per P.E. point, sees well in dim light and murky water with glare-filtering eyes; eats raw fish. Haven Mutant traits (p.60): immune to the Madhaven psychic imprint, empathic transmission, Entity fear and Horror Factor, and mind or emotion affecting psionics and magic; still hurt by physical psionics, most magic and physical attacks. Juicer conversion does not work; M.O.M. implants kill in 1D6 days; cannot learn to pilot power armor or robots.', 'None; shuns magic.', 'Not a psychic (saves vs psionics on 15), but has Electrokinesis and Hydrokinesis as innate powers; I.S.P. M.E. x10 plus 1D6 per level.', '7-8 ft (2.1-2.4 m) at the shoulder, with a 7-8 ft neck (reach 7-8 ft, head carried 9-10 ft up) and a 7-9 ft tail', '700-1200 lbs (315 to 540 kg)', 'Could reach 140; average males 2D6+56, females 2D6+60', 'Waterways, bridges, crumbling docks and sewers of Madhaven; half their time spent underwater', 'Own clan and other mutants; a wary truce with the White Rose knights, whose use of technology they also resent; trade with Horune Pirates and Slavers', 'Invaders and outsiders in general, madmen, ghosts, Undead Horrors, monsters and magic creatures; wary of Barbarians, Splugorth Minions and Horune Pirates; scorn the Coalition States, Magic Zone spell casters and Mystic Knights', NULL, 'Hairless, scaled, dinosaur-shaped amphibious mutants with long necks, tentacle feelers and toothy sea-lion faces, who reject both technology and magic and see humans as a dying breed.', 'Rifts World Book 29: Madhaven p.62-64'),
('leopard-men', 'Leopard Men', 'mutant', 'rifts', 1, 'Any; most are Unprincipled (20%), Anarchist (40%) or Aberrant (20%)', '{"IQ":"1D6+9","ME":"1D6+9","MA":"1D6+8","PS":"2D6+23","PP":"2D6+13","PE":"2D6+13","PB":"2D6+3","Spd":"2D6+17"}', NULL, NULL, '3D4x10+PE', 'PE', NULL, 'MDC: plus 2D6 per level of experience; recovers 5D6 M.D.C. per 12 hours of rest. P.S. is Robotic (full strength and power punches do M.D.). Spd doubles running on all fours. H.F. 13 in a war or hunting band of 6+. Average NPC level 1D6+4.', NULL, 10, '{"attacks":6,"initiative":3,"strike":3,"parry":3,"dodge":3,"disarm":2,"pull":5,"roll":3}', 'Six attacks at level 1, gaining one at levels 3/5/8/12/15. +3 to automatic dodge, Perception +2; saves: Horror Factor +5, mind control +2, possession +4; balance +6; immune to disease, so spoiled meat is safe to eat. Shaman overlay (p.79): a clan Shaman of this race adds +2 I.Q., +1D4+2 M.A., +3D6+10 P.P.E. (+1D6 per level), a set of lore and healing skills that replace Secondary, Pilot and W.P. Modern skills, and prayers to Isis.', 'Climbing +15%, Escape Artist +10%, two Espionage skills +10%, First Aid +10%, Horsemanship: Exotic, Hunting, Intelligence +15%, Interrogation +15%, Land Navigation +20%, Language: American (native), Math: Basic +10%, Prowl +20%, Skin & Prepare Animal Hides +15%, Tailing +15%, Tracking: People +20%, Trap & Track Animals +15%, Wilderness Survival +10%, W.P. Sword, W.P. four Ancient, W.P. one Modern; 1D4+2 Secondary Skills plus one more at levels 2, 4, 6, 8, 10, 12 and 14.', 'Leaps one foot per P.S. point (at least 25 ft) long or high from a standstill, 30% more running; a loping run on all fours doubles speed and grants an automatic dodge; a huge fanged maw bites for 2D6+2 M.D. Haven Mutant traits (p.60): immune to the Madhaven psychic imprint, empathic transmission, Entity fear and Horror Factor, and mind or emotion affecting psionics and magic; still hurt by physical psionics, most magic and physical attacks. Juicer conversion does not work; M.O.M. implants kill in 1D6 days; cannot learn to pilot power armor or robots.', 'None; avoids magic but will use a magic item when it makes tactical sense.', 'None.', '5 ft to 5 ft 10 in (1.5 to 1.75 m)', '170-200 lbs (76.5-90 kg) of solid muscle', 'Could reach 100; average males 1D6+36, females 2D6+44', 'Surface forests, tall ruins and cavern-like ruin walls of Madhaven; rogue Guardia and allied clans also camp near Jersey Side, in Maryland and among the Montreal pirates', 'Mostly their own race and clan; like the Savage Lummox and Mantis Men best; trade with Horune Pirates, Slavers, Barbarians and secretly the Shemarrians, trusting none', 'Invaders and outsiders in general, madmen, ghosts, Undead Horrors, monsters and magic creatures; the Guardia tribe also hates the White Rose knights and the Garden folk', NULL, 'Short, heavily muscled mutants with leopard-spotted skin, manes and feline heads full of teeth; the fiercest warriors of Madhaven, who raid, enslave and even eat outsiders, the Guardia tribe worst of all.', 'Rifts World Book 29: Madhaven p.64-66'),
('mantis-men', 'Mantis Men', 'mutant', 'rifts', 1, 'Any; most are Unprincipled (20%), Anarchist (40%) or Miscreant (25%)', '{"IQ":"1D6+16","ME":"1D6+15","MA":"2D6","PS":"2D6+14","PP":"1D6+15","PE":"2D6+6","PB":"1D6","Spd":"2D6+9"}', NULL, NULL, '2D4x10+PE', '3D6+PE', 'MEx5', 'MDC: plus 1D10 per level of experience. ISP: plus 1D6+1 per level. P.S. is Robotic (power punches and kicks do M.D.). Horror Factor 13 for two or more. Average NPC level 1D6+4.', NULL, 10, '{"attacks":4,"parry":1,"pull":2,"roll":1}', 'Attacks per Hand to Hand: Basic (four at level one); damage per the Robotic P.S. table. +2 to automatic dodge, +5 to save vs Horror Factor, +2 vs poison and drugs, +5 vs possession, +3 on Perception Rolls. Shaman overlay (p.79): a clan Shaman of this race adds +2 I.Q., +1D4+2 M.A., +3D6+10 P.P.E. (+1D6 per level), a set of lore and healing skills that replace Secondary, Pilot and W.P. Modern skills, and prayers to Isis.', 'Appraise Goods +15%, Anthropology +20%, Barter +10%, two Communications skills +15%, Computer Operation +20%, General Repair & Maintenance +10%, Land Navigation +10%, Language: American (native), Literacy: American +10%, four Lores, Math: Basic +20%, two Medical or Science skills +10%, Philosophy +15%, Psychology +10%, Prowl +10%, Radio: Basic +15%, W.P. two Ancient, W.P. one Modern, Hand to Hand: Basic (fixed); 1D4+2 Secondary Skills plus two more at levels 3, 5, 7, 9, 11 and 13.', 'Keen, analytical minds with a gift for study, science and psionics, and Robotic strength in a spindly frame. Haven Mutant traits (p.60): immune to the Madhaven psychic imprint, empathic transmission, Entity fear and Horror Factor, and mind or emotion affecting psionics and magic; still hurt by physical psionics, most magic and physical attacks. Juicer conversion does not work; M.O.M. implants kill in 1D6 days; cannot learn to pilot power armor or robots.', 'None; avoids magic.', 'Major Psychic (saves vs psionics on 10): Remote Viewing, See Aura, See the Invisible, Sense Magic, Sixth Sense, Total Recall and Mind Bolt. I.S.P. M.E. x5 plus 1D6+1 per level.', '12-14 ft (3.6-4.3 m), but hunch to about 10 ft (3 m)', '180-240 lbs (81 to 108 kg)', '90, some to 125; males outlive females by 10-20 years', 'Ruins above and below ground wherever there are people to watch; often wander in pairs or alone', 'Other mutants, Leopard Men most of all; a wary truce with the White Rose knights; fascinated by the Splugorth and their minions', 'Invaders and outsiders in general, madmen, ghosts, Undead Horrors, monsters and magic creatures; dislike bullies, Barbarians and Horune Pirates, yet deal with them if they must', NULL, 'Tall, stilt-legged, wedge-headed mutants shaped like a praying mantis; cold, scholarly observers of other people who consider themselves above humans and favor a hard line against outsiders.', 'Rifts World Book 29: Madhaven p.66-68'),
('metal-morph', 'Metal Morph', 'mutant', 'rifts', 1, 'Any; most are Principled (10%), Scrupulous (30%) or Unprincipled (30%), and inclined to help others', '{"IQ":"1D6+20","ME":"1D6+18","MA":"1D6+16","PS":"2D6","PP":"1D6+3","PE":"1D6+5","PB":"1D6+1","Spd":"1D6"}', NULL, NULL, '1D6x10+32', '3D6+PE', 'MEx5', 'MDC: plus 2D6+10 per level of experience; this is a hard cap on how much fused metal the body can hold. Fusing scrap restores 3D6+10 M.D.C. per half hour of work. ISP: plus 1D6+3 per level. P.S. is ordinary human strength. Average NPC level 1D6+5.', NULL, 9, '{"attacks":4,"roll":3}', 'Four attacks at level 1, gaining one at levels 3/7/14. +3 on Perception Rolls, +2 to save vs Horror Factor, +6 vs disease; impervious to disease and possession; immune to S.D.C. fire and half damage from M.D. fire. Penalties: frail and slow with almost no combat bonuses; cannot swim. Shaman overlay (p.79): a clan Shaman of this race adds +2 I.Q., +1D4+2 M.A., +3D6+10 P.P.E. (+1D6 per level), a set of lore and healing skills that replace Secondary, Pilot and W.P. Modern skills, and prayers to Isis.', 'Barter +10%, Basic Electronics +10%, Basic Mechanics +5%, two Communications skills +15%, Computer Operation +15%, History: Pre-Rifts +16%, History: Post-Apocalypse +15%, Language: American (native), Literacy: American +10%, Math: Basic +20%, Recycling +20%, Research +10%, Salvage +20%, four Science skills +15%, two Technical skills (not Lore) +15%, Xenology +20%, W.P. one Modern, Hand to Hand: none; 1D4+5 Secondary Skills plus two more at levels 2, 4, 7, 10, 12 and 15.', 'Fuses scrap metal (including M.D.C. material) onto a failing body as an outer shell, with no built-in weapons or sensors and never spikes or blades; can briefly absorb a metal object to learn its composition and value (84% +1% per level). Haven Mutant traits (p.60): immune to the Madhaven psychic imprint, empathic transmission, Entity fear and Horror Factor, and mind or emotion affecting psionics and magic; still hurt by physical psionics, most magic and physical attacks. Juicer conversion does not work; M.O.M. implants kill in 1D6 days; cannot learn to pilot power armor or robots.', 'None; intrigued by Techno-Wizardry but avoids magic.', 'Major Psychic (saves vs psionics on 10): Detect Psionics, Empathy, Meditation, Mind Block, Machine Ghost, Object Read, Telekinesis, Telekinetic Punch, Telekinetic Push, plus Super powers Mind Block Auto-Defense, Mind Bond, Psionic Invisibility, Telekinetic Acceleration Attack and Telemechanic Possession. I.S.P. M.E. x5 plus 1D6+3 per level.', '4-5 feet (1.2 to 1.5 m); often in a wheelchair or carried', '120-160 lbs (54 to 72 kg)', '60, some to 80', 'Madhaven ruins above and below ground; rarely leave, feeling too exposed', 'Most open of the mutants toward outsiders; friendly with most mutants, especially Beast Men and Pseudo Men, and with the Knights of the White Rose; clash with Mantis Men', 'Splugorth and minions; outsiders who lean hard on technology; invaders, madmen, ghosts, Undead Horrors, monsters and magic creatures; avoid Horune Pirates and slavers', NULL, 'Frail, withered mutants who survive by fusing metal scrap into a puppet-like shell; gentle, scholarly psychics who hope the mutants will guide humanity rather than replace it.', 'Rifts World Book 29: Madhaven p.68-70'),
('pseudo-men', 'Pseudo Men', 'mutant', 'rifts', 1, 'Any; typical split Anarchist 30%, Scrupulous 20%, Unprincipled 20%, Principled 10%, Aberrant 10%', '{"IQ":"1D6+10","ME":"1D6+10","MA":"1D6+10","PS":"2D6+13","PP":"2D6+9","PE":"2D6+10","PB":"1D6+4","Spd":"2D6+8"}', NULL, NULL, '2D4x10+PE', 'PE+1D6', NULL, 'MDC: plus 2D4 per level of experience in the stat block (the Natural Abilities text says 2D4+2 per level); recovers 3D6 M.D.C. per 24 hours; several oddity-table results add M.D.C. P.B. is +18 for the rare beauties. P.S. is Robotic. Horror Factor is none for human-looking ones and 14 when commanding Head Worms. Average NPC level 1D6+3.', NULL, 10, '{"attacks":4,"initiative":1,"strike":1,"parry":1,"dodge":1,"pull":2,"roll":4}', 'Attacks per Hand to Hand: Expert (four at level one); damage per the Robotic P.S. table. Saves: Horror Factor +5, mind control +6, possession +6; balance +5; Perception +1. Shaman overlay (p.79): a clan Shaman of this race adds +2 I.Q., +1D4+2 M.A., +3D6+10 P.P.E. (+1D6 per level), a set of lore and healing skills that replace Secondary, Pilot and W.P. Modern skills, and prayers to Isis.', 'Climbing +15%, Fishing +10%, First Aid +10%, Hunting, Land Navigation +20%, Language: American (native), Leather Working +15%, Math: Basic +5%, Prowl +10%, Salvage +10%, Skin & Prepare Animal Hides +15%, Spelunking +15%, Tailing +10%, Tracking +10%, Trap & Track Animals +15%, Wilderness Survival +10%, W.P. Energy Pistol, W.P. Knife or Spear, two Ancient W.P.s, two Modern W.P.s, Hand to Hand: Expert (fixed); 1D6+2 Secondary Skills plus two more at levels 2, 5, 8, 11 and 14.', 'Worms, snakes and serpents never attack them and obey them (the Giant Ruin Worm only attacks them last); 1D4 Head Worms serve as loyal pets. Roll 1D4 times on a percentile oddity table (NPCs usually have two or three): speed and reflexes, Supernatural P.S. with a quirk, 1D4 extra arms, superior climbing, fangs (bite 2D4+2), extra horns (butt 2D6), tech aptitude, an extra eye with a vision power, tough, scaly or bronze skin adding M.D.C., clown or hunter skills, superior intellect, angelic beauty, nightstalker, demon slayer, ghost charmer, or divine mutant (blows count as M.D. and hurt Entities). Haven Mutant traits (p.60): immune to the Madhaven psychic imprint, empathic transmission, Entity fear and Horror Factor, and mind or emotion affecting psionics and magic; still hurt by physical psionics, most magic and physical attacks. Juicer conversion does not work; M.O.M. implants kill in 1D6 days; cannot learn to pilot power armor or robots.', 'None; distrust magic and its users.', 'None.', '5-7 ft (1.5-2.1 m)', '100-300 lbs (45 to 135 kg)', 'Could reach 100; average males 1D6+40, females 2D6+50', 'Above and below ground in Madhaven, many in the few buildings still standing', 'Own clan and other mutants; a wary truce with the White Rose knights; trade with Horune Pirates and Slavers without trusting them', 'Invaders and outsiders in general, madmen, ghosts, Undead Horrors, monsters and magic creatures; wary of Barbarians, Splugorth Minions and Horune Pirates, though trade goes on with each', NULL, 'The most human-looking Haven Mutants, usually crowned with horns and carrying extra eyes or other odd traits, a few strikingly beautiful; brash, thrill-seeking fighters who like tech weapons and armor.', 'Rifts World Book 29: Madhaven p.71-73'),
('quill-men', 'Quill Men', 'mutant', 'rifts', 1, 'Any; typical split Anarchist 50%, Unprincipled 25%, Miscreant 10%', '{"IQ":"1D6+8","ME":"1D6+10","MA":"2D6+9","PS":"2D6+16","PP":"2D6+12","PE":"2D6+4","PB":"2D6","Spd":"3D6+2"}', NULL, NULL, '1D6x10+40+PE', '1D6+PE', NULL, 'MDC: plus 1D6 per level of experience. The quill crown over head, neck and back counts as another 400 M.D.C. against attacks from behind and cushions falls. P.S. is Bionic/Augmented. Horror Factor none normally, 12 when four or more charge in on motorcycles. Average NPC level 1D4+2.', NULL, NULL, '{"attacks":4,"initiative":2,"strike":1,"parry":1,"pull":2,"roll":4}', 'Attacks per Hand to Hand: Expert (four at level one), +1 attack from level two. dodge +3 at the wheel of a fast vehicle, disarm +4 with a Called Shot from a modern gun, +1 to strike with a gun or thrown weapon from a moving vehicle, +3 to save vs Horror Factor, +2 vs mind control, +3 vs possession, +1 on Perception Rolls. Shaman overlay (p.79): a clan Shaman of this race adds +2 I.Q., +1D4+2 M.A., +3D6+10 P.P.E. (+1D6 per level), a set of lore and healing skills that replace Secondary, Pilot and W.P. Modern skills, and prayers to Isis.', 'Appraise Goods +20%, Barter +12%, Detect Ambush +10%, Land Navigation +30%, Language: American (native), Math: Basic +5%, Pilot Hovercycles +15%, Pilot Motorcycles +20% (unicycle included), Pilot two ground vehicles +10%, Radio: Basic +10%, Recognize Weapon Quality +15%, Roadwise (Madhaven & Jersey Side) +20%, three Rogue skills +10%, Salvage +10%, Gymnastics +10%, W.P. one Ancient, W.P. three Modern, Hand to Hand: Expert (fixed); 1D4+2 Secondary Skills plus one more at levels 3, 6, 9, 12 and 15.', 'Superb balance and a daredevil nerve; rides a motorized unicycle with no hands. Quills plucked from head and back serve as M.D. daggers or whips (1D8x10+60 quills at a time; daggers regrow in 1D4 weeks, whips in 1D6+4; plucked quills crumble after 2D6+6 hours). Haven Mutant traits (p.60): immune to the Madhaven psychic imprint, empathic transmission, Entity fear and Horror Factor, and mind or emotion affecting psionics and magic; still hurt by physical psionics, most magic and physical attacks. Juicer conversion does not work; M.O.M. implants kill in 1D6 days; cannot learn to pilot power armor or robots.', 'None; avoids magic.', 'None.', '5 ft to 5 ft 6 in (1.5 to 1.75 m)', '100-140 lbs (45 to 63 kg)', '80, but average 1D6+34; females live 1D10 years longer', 'Madhaven ruins at ground level, favoring tunnels, sewers and caves; territory tagged with spray paint', 'Trade partners include other mutants, Garden folk, bandits, barbarians, adventurers and Horune Pirates; fond of the White Rose knights and quick to help them', 'Invaders and outsiders in general, madmen, ghosts, Undead Horrors, monsters and magic creatures; wary of Slavers, Barbarians, Splugorth Minions and Horune Pirates; love to harass Leopard Men, Savage Lummox and Mantis Men', NULL, 'Small, rat-faced mutants with a porcupine crest of M.D.C. quills; speed-mad raiders on Beast Men-built unicycles who would rather terrify and rob outsiders than kill them.', 'Rifts World Book 29: Madhaven p.73-76'),
('savage-lummox', 'Savage Lummox', 'mutant', 'rifts', 1, 'Any; most are Scrupulous (35%), Unprincipled (30%) or Anarchist (20%)', '{"IQ":"1D4+5","ME":"2D6+6","MA":"2D6+2","PS":"2D6+30","PP":"2D6+6","PE":"3D6+4","PB":"1D6","Spd":"2D6+2"}', NULL, NULL, '3D6x10+PE', '1D6x10', NULL, 'MDC: plus 2D6 per level of experience; recovers 2D6 M.D.C. per hour. PPE: plus 1D10 per level. P.S. is Supernatural. I.Q. of 6-7 is typical. Horror Factor 15 when facing six or more. Average NPC level 1D4+2.', NULL, 13, '{"attacks":5,"strike":4,"parry":2,"dodge":1,"disarm":2,"pull":4,"roll":1}', 'Five attacks at level 1, gaining one at levels 2/4/6/9/12/15; damage per the Supernatural P.S. table, never less than 4D6 M.D. from a punch. +2 to entangle, +8 to save vs Horror Factor, +2 vs mind control, +4 vs possession, +4 vs poison and drugs. Shaman overlay (p.79): a clan Shaman of this race adds +2 I.Q., +1D4+2 M.A., +3D6+10 P.P.E. (+1D6 per level), a set of lore and healing skills that replace Secondary, Pilot and W.P. Modern skills, and prayers to Isis.', 'Climbing +10%, Firefighting +10%, General Repair & Maintenance +10%, Horsemanship: Exotic, Interrogation +20%, Land Navigation +10%, Language: American (native), Radio: Basic +10%, Running at half its normal bonus; Skin & Prepare Animal Hides +10%, Swimming +10%, Tailing +10%, Tracking: People +10%, Wilderness Survival +10%, two Wilderness skills +10%, W.P. Blunt, W.P. three Ancient, W.P. two Modern; 1D4+1 Secondary Skills plus one more at levels 3, 6, 9, 12 and 15. Illiterate.', 'Secretes a glue-like resin from the mouth used to build scrap armor; heals fast; unknowingly spends P.P.E. to fire energy bolts from the hands (S.D.C. or M.D. versions, doubled on a ley line using ambient energy). Haven Mutant traits (p.60): immune to the Madhaven psychic imprint, empathic transmission, Entity fear and Horror Factor, and mind or emotion affecting psionics and magic; still hurt by physical psionics, most magic and physical attacks. Juicer conversion does not work; M.O.M. implants kill in 1D6 days; cannot learn to pilot power armor or robots.', 'None as such; the energy bolts draw on P.P.E. without the mutant knowing it. Avoids magic because the Shamans forbid it.', 'None.', '8-10 feet (2.4 to 3 m)', '500-800 lbs (225 to 360 kg)', 'Could reach 90; average 2D6+45 for both sexes', 'Caves, basements and tunnels among the ruins; in Madhaven and also Jersey Side', 'Fiercely loyal to all Haven Mutants and the Shamans; fond of the White Rose knights, their squires and the Garden folk, though they hide it from Mantis and Leopard Men; trade with pirates', 'Invaders, slavers, madmen, ghosts, Undead Horrors, monsters and magic creatures; wary of Barbarians, Splugorth Minions and Horune Pirates, though trade goes on with each', NULL, 'Huge, dim but steady brutes in clanking home-glued scrap armor, some horse-headed and fanged; the self-appointed guardians of mutant Madhaven, who also shield human and D-Bee women and children.', 'Rifts World Book 29: Madhaven p.76-79');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('sir-geoffrey-colt', 'Sir Geoffrey Colt', 'Geoffrey Colt', 'The Ascended; heads the Council of Seven and leads the Order of the White Rose', 'rifts', 'Human, transformed into a Mega-Damage being', '15th level Mystic Knight', 15, 'Principled', '44', '6 feet, 4 inches (1.9 m)', '218 pounds (98 kg)', '{"IQ":17,"ME":15,"MA":13,"PS":31,"PP":24,"PE":17,"PB":17,"Spd":39}', NULL, NULL, 302, 313, 97, NULL, 14, '{"attacks":10,"initiative":5,"strike":7,"parry":13,"dodge":13,"roll":8,"disarm":4,"entangle":2,"pull":8}', 'Physical attributes count as supernatural; Hit Points and S.D.C. are replaced by M.D.C. Horror Factor is his Awe Factor, which works as H.F. against enemies. Body flip, knockout/stun 18-20, automatic knockout and deathblow on a natural 20, critical strike 18-20, critical or knockout and triple damage from behind. +7 to save vs Horror Factor, +4 on Perception Rolls, +4 vs poison, +4 vs possession, +2 vs magic; impervious to disease. W.P. bonuses on top of hand to hand: Sword +5 strike and parry, Shield +3 strike and +8 parry, Energy Rifle +7 strike, Energy Pistol +7 strike. With the Twins: +2 initiative and +5 strike (no other W.P. strike bonus applies).', '[{"name":"Cook","pct":45},{"name":"First Aid","pct":98},{"name":"Horsemanship: Knight (98%/98%)","pct":98},{"name":"Horsemanship: Exotic (98%/98%)","pct":98},{"name":"Pilot: Hovercycle","pct":98},{"name":"Interrogation","pct":75},{"name":"Land Navigation","pct":78},{"name":"Lore: Magic","pct":90},{"name":"Lore: Demons & Monsters","pct":90},{"name":"Detect Ambush","pct":95},{"name":"Wilderness Survival","pct":90},{"name":"Tracking","pct":85},{"name":"Palming","pct":85},{"name":"Pick Pockets","pct":90},{"name":"Prowl","pct":90},{"name":"Trap Detection","pct":90},{"name":"Climbing","pct":85},{"name":"Swim","pct":98},{"name":"Streetwise","pct":64},{"name":"Language: American","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Language: Dragonese","pct":98},{"name":"Language: Demongogian","pct":98}]', 'Percentages include I.Q. bonuses. No percentage printed for Hand to Hand: Martial Arts, Boxing, Running, Sniper, Athletics, Wrestling. W.P.s: Energy Pistol, Energy Rifle, Paired Weapons, Shield, Sword.', 'Has every P.P.E. Channeling power of a Knight of the White Rose at double damage and range, and draws three times the normal energy from ley lines. A Mega-Damage being with Supernatural P.E. and P.S. plus enhanced agility and speed; bio-regenerates 1D6 M.D.C. per melee round. His eyes blaze with bluish-white light when roused.', 'Armor Bizarre, Armor of Ithan, Aura of Death, Blind, Blinding Flash, Call Lightning, Carpet of Adhesion, Chameleon, Climb, Compulsion, Control/Enslave Entity, Create Water, Cure Illness, Death Curse, Domination, Energize Spell, Fireball, Fists of Fury, Fly, Globe of Daylight, Heal Wounds, Invisibility: Simple, Lifeblast, Light Blade, Magic Net, Magic Pigeon, Magic Shield, Magic Warrior, Mental Blast, Meteor, Power Bolt, Power Weapon, Reduce Self, Rift Teleportation, Shadow Meld, Swim as Fish: Superior, Teleport: Lesser, Time Slip, Tongues, Wave of Frost.', 'Alter Aura, Astral Projection, Commune with Spirits, Empathy, Intuitive Combat, Mind Block, Psi-Sword (14D6 M.D.), Resist Fatigue, Resist Hunger, Resist Thirst, See Aura, See the Invisible, Sense Evil, Sense Magic, Sixth Sense, Summon Inner Strength, Telekinesis, Telekinesis: Super, Telekinetic Leap, Telekinetic Punch, Telekinetic Push, Telepathy, Total Recall.', NULL, 'None.', 'Two TW Conduit Swords and a TW Storm Rifle, with access to any TW weapon the Order''s Techno-Wizards make and to the Lockdown in the Met. The Twins, Isabella (I.Q. 14) and Mariana (I.Q. 13): a pair of flintlock pistols that are Greatest Rune Weapons, usable only together and only by a Principled wielder; they carry the eight standard Lesser Rune Weapon abilities, grant trick shooting, and can Heal Wounds (2D6 H.P. and 2D6 S.D.C., or 1D6 M.D.C.) six times a day and Remove Curse (56%) twice a day. Prefers heavy Maximilian-style TW body armor but keeps his original Mystic Knight armor. Always carries a worn, annotated copy of Erin Tarn''s Traversing our Modern World and his daily journal.', 'Up to 100,000 credits on call through the front company Bethesda Mercenary Enterprises, plus 2D6x10,000 credits in pre-Rifts artifacts.', 'Quiet, introverted and reflective; a compassionate, merciful strategist who has set aside hatred and revenge but leads decisively. Worried that the Order''s hidden home in Madhaven will be found and bring war.', 'The Order of the White Rose and contacts across the Magic Zone.', 'The Order of the Mystic Knights and their evil masters; Lord Dunscon and other powers of the Magic Zone and the Federation of Magic, who have posted a 100 million credit reward for the Order''s location.', 'A former street thief taken in by the Mystic Knights who broke with them over the massacre at Bloom and founded the Order of the White Rose; his recent ''Ascension'' turned him into a Mega-Damage being of mystic energy.', 'Rifts World Book 29: Madhaven p.38-41'),
('sir-gabriel-prescott-davenport', 'Sir Gabriel Prescott Davenport', 'Gabriel Prescott Davenport', 'The Angel of Light, Gabriel the Good; member of the Council of Seven', 'rifts', 'Human mutant from an alternate Earth', 'Mystic Knight (White Rose), 8th level, limited abilities; Mega-Hero, 1st level', 8, 'Principled', '28', '6 feet, 1 inch (1.8 m)', '181 pounds (81.5 kg)', '{"IQ":17,"ME":14,"MA":22,"PS":31,"PP":31,"PE":15,"PB":30,"Spd":20}', NULL, NULL, 178, 191, 4, NULL, 16, '{"attacks":9,"initiative":4,"strike":10,"parry":12,"dodge":12,"roll":8,"disarm":4,"entangle":2,"pull":7}', 'level is the Mystic Knight level; he is also a 1st level Mega-Hero. P.S. is Supernatural; Hit Points and S.D.C. are covered by M.D.C. Horror Factor is printed as Horror/Awe Factor. Kick attack, body flip, knockout/stun 18-20, automatic knockout and deathblow on a natural 20, critical strike 18-20, critical or knockout and triple damage from behind, invoke trust/intimidate 65%. In flight: +1 attack, +2 initiative, +2 parry, +2 dodge under 90 mph (144 km) or +6 over it, +4 M.D. for every 20 mph (32 km) flown, holds breath 8 minutes, reaches top speed in 15 seconds. Insanity: a fixed psychotic delusion that he is the Archangel Gabriel.', '[{"name":"Horsemanship: General (90%/80%)","pct":90},{"name":"Pilot: Motorcycle","pct":62},{"name":"Pilot: Sailboats","pct":62},{"name":"Land Navigation","pct":78},{"name":"Interrogation","pct":75},{"name":"Mathematics: Basic","pct":72},{"name":"Mathematics: Advanced","pct":47},{"name":"Business and Finance","pct":62},{"name":"Computer Operation","pct":67},{"name":"Law (General)","pct":52},{"name":"Research","pct":77},{"name":"Basic Electronics","pct":57},{"name":"Radio: Basic","pct":72},{"name":"T.V./Video","pct":57},{"name":"Optics Systems","pct":57},{"name":"Lore: Magic","pct":90},{"name":"Lore: Demons & Monsters","pct":90},{"name":"Wilderness Survival","pct":90},{"name":"Tracking","pct":85},{"name":"Climbing (90%/80%)","pct":90},{"name":"Streetwise","pct":64},{"name":"First Aid","pct":98},{"name":"Cook","pct":45},{"name":"Language: Japanese","pct":80},{"name":"Language: Spanish","pct":80},{"name":"Language: German (pre-Rifts)","pct":80},{"name":"Language: Italian","pct":80},{"name":"Language: Dragonese","pct":65},{"name":"Language: American","pct":98},{"name":"Literacy: American","pct":90},{"name":"Literacy: Spanish","pct":55}]', 'Percentages include I.Q. bonuses. No percentage printed for Hand to Hand: Expert, Boxing (listed twice), Running, Athletics, Wrestling, Gymnastics. W.P.s, all 8th level: Energy Rifle, Paired Weapons, Shield, Sword.', 'White Rose Knight abilities (no psionics or spells): Connection to Squires, Fire Energy Bolts, Impervious to Energy, Ley Line Phasing, Ley Line Rejuvenation, P.P.E. Channeling, Sense Ley Lines and Magic Energy, Steal and Redirect Ley Line Energy. Wings of light (320 M.D.C. each, impervious to energy, regenerate 1D6 M.D.C. per melee round); top flying speed 360 mph (576 km), with an extra 200 mph (320 km) when diving; blinding flash; radiates light like a 100 watt bulb. Heals 4D6+12 M.D.C. after an hour of meditation or six hours of rest. Angelic face and bearing.', 'None; cannot cast spells.', 'None.', 'Energy Expulsion: Light (source of his light wings, radiance and blinding flash), Mega-Wings, Physical Perfection - all per Heroes Unlimited 2nd Ed. His energy beams are Knight training, not a super power.', 'None.', 'Two TW Inferno Blades, a TW Fireburst Rifle and a TW ''Angel Fire'' Shotgun (a Hellfire Shotgun by his own name). Magic armor taken from the museum when he joined the Council of Seven: silver with gold ivy inlay, 300 M.D.C. that regrows 4D6 an hour, weightless, silent and impervious to normal and M.D. fire.', 'Up to 100,000 credits on call through Bethesda Mercenary Enterprises, the front company he runs behind the scenes.', 'Kind, fair and deeply empathetic, but can seem cold when weighing hard decisions for the greater good; fights evil without mercy yet never recklessly endangers bystanders. Sees himself as a soldier of heaven, not a preacher.', 'Fellow Knights of the White Rose; assorted heroes and friends in the Magic Zone.', 'Any force of evil, supernatural or otherwise.', 'A wealthy New Yorker from an alternate Earth whose mutant powers gave him wings of light; pulled to Rifts Earth, he joined the White Rose Knights during their exodus, knows the Manhattan ruins better than any of them, and believes himself the Archangel Gabriel.', 'Rifts World Book 29: Madhaven p.41-43');
