-- Rifts World Book 29: Madhaven - its bestiary and its two notable knights.
-- Twenty-five creatures (migration 074) and two notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-madhaven-creatures.sql
--
-- WHAT IS HERE:
--   * the ten Monsters of Madhaven with a stat block (printed 92-109). The
--     book's eleventh heading, Undead Horrors (printed 107), prints no stats and
--     points to Rifts Dark Conversions, so it has no row;
--   * the seven Ghosts of Madhaven, all Entities (printed 109-124);
--   * the eight Haven Mutants as their NPC view (printed 60-79). They are also
--     published classes, and their slugs match the class ids, as New West's
--     playable rows do. playable is 1 on these eight only;
--   * Sir Geoffrey Colt and Sir Gabriel Prescott Davenport (printed 38-43),
--     the only named beings in the book with a stat block.
--
-- A RIFTS BOOK: an M.D.C. being's pool is its main-body M.D.C.; M.D.C. by
-- location, second speeds, per-level growth and any figure the roll grammar
-- cannot take are in pools_note. Where the book prints two Horror Factors (one
-- being, a group) the first is stored and the other is in the notes. Where the
-- book states one figure twice and differently (the Contagion Entity's P.P.E.,
-- the Pseudo Men's M.D.C. per level), the stat-block figure is stored and the
-- other is noted.
--
-- EXTRACTED by three workers, each given NAMES, with every number read off a
-- 200 dpi render - the text layer carries this book's digit cipher, and cache
-- p113 (printed 112) is welded. RECONCILED by book-reconcile against the
-- renders, row by row; its two corrections are applied (the Devil Kraken's
-- enemies came from flavour text, not its Enemies line; the Madness Ghost's
-- vulnerabilities had dropped five named spells). Every creature row passes
-- creatureFormulaGaps, the grammar the endpoint rolls with. Prose fields are
-- short paraphrases; an 8-word shingle check against the cache finds none.




-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 25 Madhaven creatures are in' AS assertion, count(*) AS got, 25 AS want
  FROM creatures WHERE slug IN ('caterpillar-man', 'devil-kraken', 'giant-ruin-worm', 'head-worm', 'onion-head', 'phantom-wolf', 'ruin-lizard', 'ruin-rat', 'toothback-wallcrawler', 'war-bird', 'gluttonous-entity', 'beautiful-ghost', 'harmful-ghost', 'madness-ghost', 'conglomerate-entity', 'contagion-entity', 'rotting-entity', 'beast-men', 'dyno-men', 'leopard-men', 'mantis-men', 'metal-morph', 'pseudo-men', 'quill-men', 'savage-lummox');
SELECT 'and 8 of them are the playable mutants' AS assertion, count(*) AS got, 8 AS want
  FROM creatures WHERE slug IN ('caterpillar-man', 'devil-kraken', 'giant-ruin-worm', 'head-worm', 'onion-head', 'phantom-wolf', 'ruin-lizard', 'ruin-rat', 'toothback-wallcrawler', 'war-bird', 'gluttonous-entity', 'beautiful-ghost', 'harmful-ghost', 'madness-ghost', 'conglomerate-entity', 'contagion-entity', 'rotting-entity', 'beast-men', 'dyno-men', 'leopard-men', 'mantis-men', 'metal-morph', 'pseudo-men', 'quill-men', 'savage-lummox') AND playable = 1;
SELECT 'both notable knights are in' AS assertion, count(*) AS got, 2 AS want
  FROM notable_npcs WHERE slug IN ('sir-geoffrey-colt', 'sir-gabriel-prescott-davenport');
SELECT 'the creatures carry 68 attacks' AS assertion, count(*) AS got, 68 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('caterpillar-man', 'devil-kraken', 'giant-ruin-worm', 'head-worm', 'onion-head', 'phantom-wolf', 'ruin-lizard', 'ruin-rat', 'toothback-wallcrawler', 'war-bird', 'gluttonous-entity', 'beautiful-ghost', 'harmful-ghost', 'madness-ghost', 'conglomerate-entity', 'contagion-entity', 'rotting-entity', 'beast-men', 'dyno-men', 'leopard-men', 'mantis-men', 'metal-morph', 'pseudo-men', 'quill-men', 'savage-lummox');
SELECT 'and the knights 6' AS assertion, count(*) AS got, 6 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('sir-geoffrey-colt', 'sir-gabriel-prescott-davenport');

-- Records this run. See db/migrations/024-data-script-runs.sql.
